#include <libakrypt.h>
/*
	Создает asn структуру с описанием алгоритма шифрования вида
	├OBJECT IDENTIFIER 1.2.643.7.1.1.5.2.2
	└SEQUENCE┐
			└OCTET STRING
            
*/
ak_asn1 create_encryption_algorithm_sequence() {
//create algoritm_shifr_sequence
	ak_asn1 encryption_algorithm_sequence = ak_asn1_new();
	if (!encryption_algorithm_sequence) return NULL;

	// add oid
	const char* oid = "1.2.643.7.1.1.5.2.2";
	if (ak_asn1_add_oid(encryption_algorithm_sequence, oid) != ak_error_ok) {
		ak_asn1_delete(encryption_algorithm_sequence);
	    return NULL;
	}

	// create seq for octet
	ak_asn1 nested_sequence = ak_asn1_new();
	if (!nested_sequence) {
		ak_asn1_delete(encryption_algorithm_sequence);
		return NULL;
	}

	//add octet data
	ak_uint8 octet_string_data[] = {0x25, 0x9A, 0xDD, 0x96, 0x0D, 0xF6, 0x8F, 0x26, 0x5B, 0x00, 0xB3, 0x49, 0x8B, 0x2A, 0x09, 0x73};
	size_t octet_string_size = sizeof(octet_string_data) / sizeof(ak_uint8);


	//add octet insto seq
	if (ak_asn1_add_octet_string(nested_sequence, octet_string_data, octet_string_size) != ak_error_ok) {
		ak_asn1_delete(encryption_algorithm_sequence);
		ak_asn1_delete(nested_sequence);
		return NULL;
	}


	//add seq to seq
	if (ak_asn1_add_asn1(encryption_algorithm_sequence, TSEQUENCE, nested_sequence) != ak_error_ok) {
		ak_asn1_delete(encryption_algorithm_sequence);
	    ak_asn1_delete(nested_sequence);
	    return NULL;
	}
	return encryption_algorithm_sequence;
}
// Создает asn структуру вида:
/*
├OBJECT IDENTIFIER 1.2.840.113549.1.5.12
└SEQUENCE┐
         ├OCTET STRING
         ├INTEGER 0x800
         └SEQUENCE┐
                  └OBJECT IDENTIFIER 1.2.643.7.1.1.4.2 
         
*/
ak_asn1 create_pbkdf2_sequence() {
	ak_asn1 pbkdf2_sequence = ak_asn1_new();
	if (!pbkdf2_sequence) return NULL;

	//add oid 
	if (ak_asn1_add_oid(pbkdf2_sequence, "1.2.840.113549.1.5.12") != ak_error_ok) {
		ak_asn1_delete(pbkdf2_sequence);
		return NULL;
	}

	//create sequence
	ak_asn1 nested_sequence = ak_asn1_new();
	if (!nested_sequence) {
		ak_asn1_delete(nested_sequence);
		ak_asn1_delete(pbkdf2_sequence);
		return NULL;
	}

	//add octet
	ak_uint8 octet_string_data[] = {0xA7, 0xF8, 0x37, 0xB3, 0x4C, 0xC2, 0xE8, 0x2A};
	if (ak_asn1_add_octet_string(nested_sequence, octet_string_data, sizeof(octet_string_data)) != ak_error_ok) {
		ak_asn1_delete(nested_sequence);
		ak_asn1_delete(pbkdf2_sequence);
		return NULL;
	}

	//add INT
	if (ak_asn1_add_uint32(nested_sequence, 0x800) != ak_error_ok) {
		ak_asn1_delete(pbkdf2_sequence);
		ak_asn1_delete(nested_sequence);
		return NULL;
	}

	// create one more seq
	ak_asn1 inner_nested_sequence = ak_asn1_new();
	if (!inner_nested_sequence) {
		ak_asn1_delete(pbkdf2_sequence);
		ak_asn1_delete(nested_sequence);
		return NULL;
	}

	//add one more oid
	if (ak_asn1_add_oid(inner_nested_sequence, "1.2.643.7.1.1.4.2") != ak_error_ok) {
		ak_asn1_delete(pbkdf2_sequence);
		ak_asn1_delete(nested_sequence);
		ak_asn1_delete(inner_nested_sequence);
		return NULL;
	}

	//add nested seq to root
	if (ak_asn1_add_asn1(nested_sequence, TSEQUENCE, inner_nested_sequence) != ak_error_ok || ak_asn1_add_asn1(pbkdf2_sequence, TSEQUENCE, nested_sequence) != ak_error_ok) {
		ak_asn1_delete(pbkdf2_sequence);
		ak_asn1_delete(nested_sequence);
		ak_asn1_delete(inner_nested_sequence);
		return NULL;
	}


	return pbkdf2_sequence;
	
	
}


// Создает asn структуру вида:
/*
├OBJECT IDENTIFIER 1.2.840.113549.1.5.13
└SEQUENCE┐
         ├SEQUENCE┐ create_pbkdf2_sequence()
         │        
         └SEQUENCE┐ create_encryption_algorithm_sequence()
                  
*/
ak_asn1 create_combined_sequence() {
	//create_top_seq
	ak_asn1 top_sequence = ak_asn1_new();
	if (!top_sequence) return NULL;

	//add oid
	if (ak_asn1_add_oid(top_sequence, "1.2.840.113549.1.5.13") != ak_error_ok) {
		ak_asn1_delete(top_sequence);
		return NULL;
	}

	//create pbkdf2 and encrypt alog seq
	ak_asn1 nested_sequence = ak_asn1_new();
	if (!nested_sequence) {
		ak_asn1_delete(top_sequence);
		return NULL;
	}

	//concat seq
	ak_asn1 pbkdf2_sequence = create_pbkdf2_sequence();
	if (!pbkdf2_sequence) {
		ak_asn1_delete(top_sequence);
		ak_asn1_delete(nested_sequence);
		return NULL;
	}

	ak_asn1 encryption_algorithm_sequence = create_encryption_algorithm_sequence();
	if (!encryption_algorithm_sequence) {
		ak_asn1_delete(top_sequence);
		ak_asn1_delete(nested_sequence);
		ak_asn1_delete(pbkdf2_sequence);
		return NULL;
		
	}
	if (ak_asn1_add_asn1(nested_sequence, TSEQUENCE, pbkdf2_sequence) != ak_error_ok || ak_asn1_add_asn1(nested_sequence, TSEQUENCE, encryption_algorithm_sequence) != ak_error_ok) {
		ak_asn1_delete(top_sequence);
		ak_asn1_delete(nested_sequence);
		ak_asn1_delete(pbkdf2_sequence);
		ak_asn1_delete(encryption_algorithm_sequence);
		return NULL;
	}

	//concat with root seq
	if (ak_asn1_add_asn1(top_sequence, TSEQUENCE, nested_sequence) != ak_error_ok) {
		ak_asn1_delete(top_sequence);
		ak_asn1_delete(nested_sequence);
		return NULL;
	}
	
	return top_sequence;
	
}


//функция для чтения файла
/*
	filename - отдука считать файл
	outSize - переменная в которую запишется размер
	Возвращает указатель на массив ak_uint8
*/
ak_uint8* p12_read_file(char* filename, size_t *outSize){
	struct file file;
    ak_uint8 buffer[48];
    size_t val = 1;
    size_t totalSize = 0;
    ak_uint8 *data = NULL;

    if(ak_file_open_to_read(&file, filename) != ak_error_ok){
            perror("Can not open file");
            return NULL;
    }

    while((val = ak_file_read(&file,buffer,sizeof(buffer))) != 0 ){
    	ak_uint8 *newData = realloc(data, totalSize+val);
        if(!newData){
        	perror("Can not realloc memmory");
            free(data);
            ak_file_close(&file);
            return NULL;
        }
        data = newData;
        memcpy(data + totalSize, buffer, val);
        totalSize += val;
    }

    ak_file_close(&file);

    if(outSize != NULL){
    	*outSize = totalSize;
    }

    return data;
}


//функция шифрования приватного ключа кузнечиком
/*
	filename - файл из которого необходимо считать приватный ключ
	password - пароль для шифрования
	buffer_size - сюда будет записан размер массива зашифрованного приватного ключа
	Возвращает указатель на массив ak_uint8 с байтами зашифрованного приватного ключа
*/
ak_uint8* private_key_encrypt(char* filename, char* password, size_t *buffer_size){
	size_t fileSize;
	ak_uint8 *fileData = p12_read_file(filename, &fileSize);
	if(fileData == NULL){
		perror("Cannot read data from file");
	}

	ak_uint8* buffer_out = (ak_uint8 *)malloc(fileSize * sizeof(ak_uint8));
	if(buffer_out == NULL){
		perror("Can not malloc memmory for buffer_out in encryption function");
	}

	ak_uint8 iv[8] = {0x03,0x07,0xae,0xf1};

	struct bckey key;
	ak_bckey_create_oid(&key, ak_oid_find_by_name("kuznechik"));
	ak_bckey_set_key_from_password(&key, password, 8, "sugar", 5);
	ak_bckey_ctr(&key, fileData, buffer_out, fileSize, iv,8);

	*buffer_size = fileSize;
	return buffer_out;
}


/*
Генерирует asn структуру с байтами зашифрованного приватного ключа
вида:
├SEQUENCE┐  
         └OCTET STRING

myarray - массив байт(Зашифрованный ключ)
array_size - размер массива
*/
ak_asn1 create_octet_string_sequence(ak_uint8 *myarray, size_t array_size) {
	ak_asn1 top_sequence = ak_asn1_new();
	if (!top_sequence) return NULL;

	ak_asn1 combined_seq = create_combined_sequence();
	if (!combined_seq) {
		ak_asn1_delete(top_sequence);
		return NULL;
	}

	if (ak_asn1_add_asn1(top_sequence, TSEQUENCE, combined_seq) != ak_error_ok) {
		ak_asn1_delete(top_sequence);
		ak_asn1_delete(combined_seq);
		return NULL;
	}

	if (ak_asn1_add_octet_string(top_sequence, myarray, array_size) != ak_error_ok) {
		ak_asn1_delete(top_sequence);
		return NULL;
	}

	return top_sequence;
}
/*
Генерирует asn типов local_key_id и friendlyName
Вида:
└SET┐
    ├SEQUENCE┐
    │        ├OBJECT IDENTIFIER 1.2.840.113549.1.9.21 local_key_id 
    │        └SET┐
    │            └OCTET STRING
    │               
    │               
    └SEQUENCE┐
             ├OBJECT IDENTIFIER 1.2.840.113549.1.9.20 friendlyName
             └SET┐
                 └OCTET STRING  
*/
ak_asn1 create_custom_asn1_sequence() {
	ak_asn1 top_sequence = ak_asn1_new();
	ak_asn1 set_sequence, nested_sequence, nested_set;
	ak_uint8 octet_string_data[] = {0x79, 0x55, 0x74, 0xF9, 0xD4, 0xB6, 0xE4, 0xC2, 0x02, 0x24, 0x28, 0x69, 0x98, 0x67, 0x3F, 0xF0, 0x0A, 0x14, 0xC0, 0x4D};
	ak_uint8 bmp_string_data[] = {0x00, 0x70, 0x00, 0x31, 0x00, 0x32, 0x00, 0x46, 0x00, 0x72, 0x00, 0x69, 0x00, 0x65, 0x00, 0x6e, 0x00, 0x64, 0x00, 0x6c, 0x00, 0x79, 0x00, 0x4e, 0x00, 0x61, 0x00, 0x6d, 0x00, 0x65}; // "p12FriendlyName" в UTF-16

	if (!top_sequence) return NULL;


	set_sequence = ak_asn1_new();
	nested_sequence = ak_asn1_new();
	nested_set = ak_asn1_new();

	if (!set_sequence || !nested_sequence || !nested_set ||
		ak_asn1_add_asn1(set_sequence, TSEQUENCE, nested_sequence) != ak_error_ok ||
		ak_asn1_add_asn1(nested_sequence, TSET, nested_set) != ak_error_ok ||
		ak_asn1_add_oid(nested_sequence, "1.2.840.113549.1.9.21") != ak_error_ok || // local_key_id
		ak_asn1_add_octet_string(nested_set, octet_string_data, sizeof(octet_string_data)) != ak_error_ok) {
			ak_asn1_delete(top_sequence);
			ak_asn1_delete(set_sequence);
			ak_asn1_delete(nested_sequence);
			ak_asn1_delete(nested_set);
			return NULL;
	}

	
	nested_sequence = ak_asn1_new();
	nested_set = ak_asn1_new();
	if (!nested_sequence || !nested_set ||
		ak_asn1_add_asn1(set_sequence, TSEQUENCE, nested_sequence) != ak_error_ok ||
		ak_asn1_add_asn1(nested_sequence, TSET, nested_set) != ak_error_ok ||
		ak_asn1_add_oid(nested_sequence, "1.2.840.113549.1.9.20") != ak_error_ok || // friendlyName
		ak_asn1_add_octet_string(nested_set, bmp_string_data, sizeof(bmp_string_data)) != ak_error_ok) {
			ak_asn1_delete(top_sequence);
			return NULL;
	}

	if (ak_asn1_add_asn1(top_sequence, TSET, set_sequence) != ak_error_ok) {
		ak_asn1_delete(top_sequence);
		return NULL;
	}
	
	return set_sequence;
	
	
}


/*
	Генерирует asn дерево для приватного ключа согласно p12 контейнеру
	filename - файл приватного ключа
	password - пароль для шифрования приватного ключа
	Возвращает asn приватного ключа вида:
	└SEQUENCE┐
         └SEQUENCE┐
                  ├OBJECT IDENTIFIER 1.2.840.113549.1.12.10.1.2 
                  ├[0]┐
                  │   └SEQUENCE┐
                  │            ├SEQUENCE┐  
                  │            │        ├OBJECT IDENTIFIER 1.2.840.113549.1.5.13 
                  │            │        └SEQUENCE┐
                  │            │                 ├SEQUENCE┐
                  │            │                 │        ├OBJECT IDENTIFIER 1.2.840.113549.1.5.12 
                  │            │                 │        └SEQUENCE┐
                  │            │                 │                 ├OCTET STRING
                  │            │                 │                 │  
                  │            │                 │                 ├INTEGER 
                  │            │                 │                 └SEQUENCE┐
                  │            │                 │                          ├OBJECT IDENTIFIER 1.2.643.7.1.1.4.2 
                  │            │                 │                          └NULL
                  │            │                 └SEQUENCE┐
                  │            │                          ├OBJECT IDENTIFIER 1.2.643.7.1.1.5.2.2 
                  │            │                          └SEQUENCE┐
                  │            │                                   └OCTET STRING
                  │            │                                      
                  │            └OCTET STRING
                  └SET┐
                      ├SEQUENCE┐
                      │        ├OBJECT IDENTIFIER 1.2.840.113549.1.9.21 
                      │        └SET┐
                      │            └OCTET STRING
                      │               
                      │               
                      └SEQUENCE┐
                               ├OBJECT IDENTIFIER 1.2.840.113549.1.9.20 
                               └SET┐
                                   └OCTET STRING  

*/
ak_asn1 create_private_key_fin_asn1_structure(char *filename,char *password) {
	size_t fileSize;
	ak_uint8 *priv_key = private_key_encrypt(filename,password, &fileSize);

	ak_asn1 top_sequence = ak_asn1_new();
	ak_asn1 top_top_sequence = ak_asn1_new();
	ak_asn1 inner_sequence, context_specific_sequence;
	if (!top_sequence) return NULL;

	inner_sequence = ak_asn1_new();
	if (!inner_sequence ||
		ak_asn1_add_oid(inner_sequence, "1.2.840.113549.1.12.10.1.2") != ak_error_ok) { // pkcs-8ShroudedKeyBag
		ak_asn1_delete(top_sequence);
		return NULL;
	}

	context_specific_sequence = create_octet_string_sequence(priv_key, fileSize);
	if (!context_specific_sequence ||
		ak_asn1_add_asn1(inner_sequence, CONTEXT_SPECIFIC^0x00, context_specific_sequence) != ak_error_ok) {
			ak_asn1_delete(top_sequence);
	}
	
	ak_asn1 custom_sequence = create_custom_asn1_sequence();
	if (!custom_sequence ||
		ak_asn1_add_asn1(inner_sequence, TSET, custom_sequence) != ak_error_ok) {
			ak_asn1_delete(top_sequence);
			ak_asn1_delete(context_specific_sequence);
			return NULL;
		}
	if (ak_asn1_add_asn1(top_sequence, TSEQUENCE, inner_sequence) != ak_error_ok) {
		ak_asn1_delete(top_sequence);
		return NULL;
	}
	if(ak_asn1_add_asn1(top_top_sequence, TSEQUENCE, top_sequence) != ak_error_ok){
		ak_asn1_delete(top_sequence);
		ak_asn1_delete(top_top_sequence);
		
	}
	return top_top_sequence;
}


//рассчет хеша
/*
filename - файл для которого считать хеш
hash_len - сюда запишется размер хеша
Возвращает массив байт(хэш)
*/
ak_uint8* calculate_hash(char* filename, size_t* hash_len){
        struct hash ctx;
        ak_uint8 *out = (ak_uint8 *)malloc(32 * sizeof(ak_uint8));
        ak_hash_create_streebog256( &ctx );
        //const char *str1 = NULL;
        size_t len = 0;

        ak_hash_file( &ctx, filename, out, len = ak_hash_get_tag_size( &ctx ));
        *hash_len = len;

        return out;
}
/*
	seq - asn от которого надо подсчитать хэш
	filename - файл куда запишется asn
	считает хэш от asn и возвращает asn вида:

	└SEQUENCE┐
         ├SEQUENCE┐
         │        ├SEQUENCE┐
         │        │        └OBJECT IDENTIFIER 1.2.643.7.1.1.2.3 
         │        └OCTET STRING
         │           
         │           
         │           
         │           
         ├OCTET STRING
         │  
         └INTEGER 

*/
ak_asn1 asn1_hash_seq(ak_asn1 seq,char *filename){
	ak_asn1_export_to_derfile(seq,filename);
	size_t hash_data_size;
	ak_uint8 *hash_data = calculate_hash(filename, &hash_data_size);


	ak_asn1 top_sequence = ak_asn1_new();
	ak_asn1 inner_sequence, oid_sequence;
	ak_uint8 octet_string_data[] = {0x85, 0x44, 0xB4, 0xEF, 0x95, 0xA6, 0xEB, 0x24};
	if (!top_sequence) return NULL;

	inner_sequence = ak_asn1_new();
	oid_sequence = ak_asn1_new();
	if (!inner_sequence || !oid_sequence ||
		ak_asn1_add_asn1(inner_sequence, TSEQUENCE, oid_sequence) != ak_error_ok ||
		ak_asn1_add_oid(oid_sequence, "1.2.643.7.1.1.2.3") != ak_error_ok || // streebog512
		ak_asn1_add_octet_string(inner_sequence, hash_data, hash_data_size) != ak_error_ok) {
			ak_asn1_delete(top_sequence);
			return NULL;
		}
	if (ak_asn1_add_asn1(top_sequence, TSEQUENCE, inner_sequence) != ak_error_ok) {
		ak_asn1_delete(top_sequence);
		return NULL;
	}


	if (ak_asn1_add_octet_string(top_sequence, octet_string_data, sizeof(octet_string_data)) != ak_error_ok) {
		ak_asn1_delete(top_sequence);
		return NULL;
	}

	if (ak_asn1_add_uint32(top_sequence, 0x800) != ak_error_ok) {
		ak_asn1_delete(top_sequence);
		return NULL;
	}

	return top_sequence;

}



//функция для преобразования asn в байты и представление ее в виде:
/*
└SEQUENCE┐
         ├OBJECT IDENTIFIER 1.2.840.113549.1.7.1 (cms-data-content-type) Я так понимаю тут начинается приватный ключ. Как он шфируется и где информация о методе его шифрования?
         └[0]┐
         	 └OCTET STRING

	seq - asn, который необходимо закодировать и представить в виде OCTET STRING
*/
ak_asn1 template_with_octet(ak_asn1 seq){
	size_t seqSize;
	if(ak_asn1_evaluate_length(seq,&seqSize) != ak_error_ok){
		return NULL;
	}

	ak_uint8 *octet_buffer = (ak_uint8 *)malloc(seqSize * sizeof(ak_uint8));

	ak_asn1_encode(seq, octet_buffer, &seqSize);

	ak_asn1 top_seq = ak_asn1_new();

	if(ak_asn1_add_oid(top_seq, "1.2.840.113549.1.7.1") != ak_error_ok){
		return NULL;
	}

	ak_asn1 context_specific = ak_asn1_new();

	if(ak_asn1_add_octet_string(context_specific, octet_buffer, seqSize) != ak_error_ok){

		ak_asn1_delete(top_seq);
		ak_asn1_delete(context_specific);
		return NULL;
	}

	if(ak_asn1_add_asn1(top_seq, CONTEXT_SPECIFIC^0x00, context_specific ) != ak_error_ok){
		return NULL;
	}
	
	return top_seq;

	
}


//Представление сертификата в виде asn p12.
/*
	filename - имя файла где лежит сертификат
	возвращает asn1 структуру сертфиката в p12 контейнере
*/
ak_asn1 cert_asn1_creator(char* filename){
	ak_asn1 cert = ak_asn1_new();
	ak_asn1_import_from_file(cert, filename, NULL);

	size_t cetSize;
	if(ak_asn1_evaluate_length(cert,&cetSize) != ak_error_ok){
			return NULL;
		}
		
	ak_uint8 *octet_buffer = (ak_uint8 *)malloc(cetSize * sizeof(ak_uint8));
	ak_asn1_encode(cert, octet_buffer, &cetSize);

	ak_asn1 top_seq = ak_asn1_new();
	if(ak_asn1_add_oid(top_seq, "1.2.840.113549.1.9.22.1") != ak_error_ok){
			return NULL;
	}

	ak_asn1 context_specific = ak_asn1_new();
	if(ak_asn1_add_octet_string(context_specific, octet_buffer, cetSize) != ak_error_ok){
		return NULL;
	}

	if(ak_asn1_add_asn1(top_seq, CONTEXT_SPECIFIC^0x00, context_specific ) != ak_error_ok){
		return NULL;
	}


	ak_asn1 pre_fin_asn = ak_asn1_new();
	
	if(ak_asn1_add_oid(pre_fin_asn,"1.2.840.113549.1.12.10.1.3") != ak_error_ok){
		return NULL;
	}
	
	ak_asn1 pre_context_specific = ak_asn1_new();
	if(ak_asn1_add_asn1(pre_context_specific, TSEQUENCE, top_seq) != ak_error_ok){
		return NULL;
	}

	if(ak_asn1_add_asn1(pre_fin_asn, CONTEXT_SPECIFIC^0x00, pre_context_specific ) != ak_error_ok){
		return NULL;
	}

	ak_asn1 custom_sequence = create_custom_asn1_sequence();
		if(ak_asn1_add_asn1(pre_fin_asn, TSET, custom_sequence) != ak_error_ok){
	
			return NULL;
		}
	ak_asn1 fin_seq = ak_asn1_new();

	if(ak_asn1_add_asn1(fin_seq,TSEQUENCE,pre_fin_asn) != ak_error_ok){
		return NULL;
	}

	ak_asn1 top_fin_seq = ak_asn1_new();

	if(ak_asn1_add_asn1(top_fin_seq, TSEQUENCE, fin_seq)){

		return NULL;
	}
	return template_with_octet(top_fin_seq);
	
}

//генерация asn p12 сертификата + приватного ключа
/*
	собирает воедино asn1 приватного ключа и сертификата
	cert - asn1 сертификата
	key - asn1 приватного ключа
*/
ak_asn1 create_prefinal_asn(ak_asn1 cert, ak_asn1 key){
	ak_asn1 top_seq = ak_asn1_new();
	if(ak_asn1_add_asn1(top_seq, TSEQUENCE, cert) != ak_error_ok){
		ak_asn1_delete(top_seq);
		return NULL;
	}

	if(ak_asn1_add_asn1(top_seq, TSEQUENCE, key) != ak_error_ok){
		ak_asn1_delete(top_seq);
		return NULL;
	}
	ak_asn1 top_top_seq = ak_asn1_new();
	if(ak_asn1_add_asn1(top_top_seq, TSEQUENCE, top_seq) != ak_error_ok){
		return NULL;
	}
	return top_top_seq;
	
}
// Генерация p12 контейнера
/*
certificate - файл с сертификатов
privatekey - файл с приватным ключом
password - пароль для шифрования приватного ключа
p12 контенйнер запишется в файл: akp12con.der
возвращает 0 в случае успеха
*/
int ak_generate_p21_container(char *certificate, char *privatekey, char *password){
	ak_asn1 privkeySeq = create_private_key_fin_asn1_structure(privatekey, password);
	
	ak_asn1 privkey_encode_asn = template_with_octet(privkeySeq);

	ak_asn1 certAsn = cert_asn1_creator(certificate);

	ak_asn1 pre_final = create_prefinal_asn(certAsn, privkey_encode_asn);
	char *file_out = "akp12con.der";

	ak_asn1 hash_seq = asn1_hash_seq(pre_final, file_out);

	ak_asn1 top_seq = ak_asn1_new();
	if(ak_asn1_add_uint32(top_seq,0x300) != ak_error_ok){

		return -1;
	}

	if(ak_asn1_add_asn1(top_seq,TSEQUENCE,pre_final ) != ak_error_ok){
		return -1;
	}

	if(ak_asn1_add_asn1(top_seq, TSEQUENCE, hash_seq) != ak_error_ok){
		return -1;
	}

	//ak_asn1_print(top_seq);
	ak_asn1_export_to_derfile(top_seq,file_out);
	return 0;
	
}


//функция поиска необходимого объека asn по его oid
/*
Рекурсивно обходит asn дерево в поисках нужного oid
asn1 - asn где искать
found_asn1 - сюда запишется корень найденного asn1 у которого oid равен искомуму
search_oid - oid который нужно найти
возвращает 0 в случае успеха
*/
int my_rec_asn(ak_asn1 asn1,ak_asn1 *found_asn1,char * search_oid){
	ak_asn1_first(asn1);

	do{

		if(asn1->current->tag == 4){
			ak_asn1 octet_str = ak_asn1_new();
			ak_asn1_decode(octet_str, asn1->current->data.constructed,asn1->current->len,ak_false);
			if(my_rec_asn(octet_str,found_asn1,search_oid) == 0){
				return 0;
			}
		}
		if(asn1->current->tag == 48 || asn1->current->tag == 160){
			if(asn1->current->tag == 48){
				ak_asn1 sq = NULL;
				ak_asn1_first( sq = asn1->current->data.constructed );
				
				ak_pointer ptr = NULL;
				if(ak_tlv_get_oid( sq->current, &ptr ) == ak_error_ok){
					if( strncmp( (char*)ptr, search_oid, strlen( search_oid )) == 0 ){
						*found_asn1 = asn1->current->data.constructed;
						return 0;
					}
					
				}
			}
			if(my_rec_asn(asn1->current->data.constructed,found_asn1,search_oid) == 0){
				return 0;
			}
		}
	}while(ak_asn1_next(asn1));
	
	return -1;
}


// достает массив байт зашифрованного приватного ключа из p12 контейнера
/*
asn1 - asn1 структура приватного ключа
output_array - область памяти куда запишется найденный байты
output_size - размер приватного ключа
возвращает ak_error_ok в случае успеха
*/
int get_encr_key_from_asn(ak_asn1 asn1, ak_uint8 **output_array, size_t *output_size){
	ak_asn1_first(asn1);
	do{
		//printf("\n%s\n", ak_asn1_get_tag_description(asn1->current->tag));
		if(asn1->current->tag == 160){
			ak_asn1 sq = NULL;
			ak_asn1_first(sq = asn1->current->data.constructed);
			do{
				//printf("\n%s\n", ak_asn1_get_tag_description(sq->current->tag));
				//printf("%d", sq->current->tag);
				if(sq->current->tag == 4){
					*output_size = sq->current->len;
					*output_array = (ak_uint8 *)malloc(*output_size);
					
					ak_uint8 *octet_data = (ak_uint8 *)sq->current->data.primitive;
					memcpy(*output_array, octet_data, *output_size);
					return ak_error_ok;

					
					//ak_uint8 *octet_data = (ak_uint8 *)sq->current->data.primitive;
					//size_t octet_data_size = sq->current->len;

					
					
					
				}
			}while(ak_asn1_next(sq));
		}
	}while(ak_asn1_next(asn1));

	return -1;
}

//записиывает массив байт в файл
/*
filename куда записать
data - что записать
dataSize - размер
возвращает 0 в случае успеха
*/
int p12_write_data_to_file(char* filename, ak_uint8 *data, size_t dataSize){
        struct file file;
        if(ak_file_create_to_write(&file, filename) != ak_error_ok){
                perror("Can not create file for writing");
                return -1;
        }

        size_t written = ak_file_write(&file,data, dataSize);
        if(written != dataSize){
                perror("Error while writing to file");
                ak_file_close(&file);
                return -1;
        }

        ak_file_close(&file);
        return 0;
}
//функция расшифрования приватного ключа из p12 контейнера
/*
filename - куда записать приватный ключ
password - пароль для расшифрования
fileData - байты зашифрованного приватного ключа
fileSize - размер
*/
void p12_private_key_decrypt(char* filename,char* password, ak_uint8 *fileData, size_t fileSize){
        //decdata
        ak_uint8* buffer_out = (ak_uint8*)malloc(fileSize * sizeof(ak_uint8));
        if(buffer_out == NULL){
                perror("Can not malloc memmory in dec function");
        }

        ak_uint8 iv[8] = {0x03,0x07,0xae,0xf1};

        struct bckey key;
        ak_bckey_create_oid(&key, ak_oid_find_by_name("kuznechik"));
        ak_bckey_set_key_from_password(&key,password,8,"sugar",5);
        ak_bckey_ctr(&key, fileData, buffer_out, fileSize, iv,8);
        p12_write_data_to_file(filename,buffer_out, fileSize);
}

// функция извлеченения приватного ключа из файла
/*
asn1 - asn1 p12 контейнера
password - пароль для расшифрования
возвращает 0 в случае успеха
*/
int extract_privatekey_from_asn(ak_asn1 asn1,char *password){
	ak_asn1 private_key_asn = ak_asn1_new();
	ak_uint8 *encr_data;
	size_t encr_data_size;
	char * search_oid = "1.2.840.113549.1.12.10.1.2";
	char *out_file = "extractedprivkey.der";


	if(my_rec_asn(asn1, &private_key_asn,search_oid) == 0){
		if(get_encr_key_from_asn(private_key_asn,&encr_data,&encr_data_size) == ak_error_ok){
			p12_private_key_decrypt(out_file, password, encr_data, encr_data_size);
			return 0;
		}
		
	}

	return -1;
		
}
//функция извлечения сертификата из p12 контейнера
/*
asn1 - asn1 p12 контейнера
возвращает 0 в случае успеха
*/	
int extract_cert_from_p12(ak_asn1 asn1){
	ak_asn1 cert_asn = ak_asn1_new();
	char * search_oid = "1.2.840.113549.1.9.22.1";
	char *file_out = "extractedcertp12.der";
	
	if(my_rec_asn(asn1, &cert_asn,search_oid) == 0){
		//ak_asn1_print(cert_asn);
		ak_asn1_first(cert_asn);
		do{
			//printf("\n%s\n", ak_asn1_get_tag_description(cert_asn->current->tag));
			if(cert_asn->current->tag == 160){
				//printf("\n%s\n", ak_asn1_get_tag_description(cert_asn->current->tag));
				ak_asn1 sq = NULL;
				ak_asn1_first( sq = cert_asn->current->data.constructed );
				//printf("\n%s\n", ak_asn1_get_tag_description(sq->current->tag));

				ak_asn1 cert_der_asn = ak_asn1_new();
				ak_asn1_decode(cert_der_asn,sq->current->data.constructed, sq->current->len, ak_false);

				ak_asn1_export_to_derfile(cert_der_asn,file_out);
				return 0;
				
			}
			
		}while(ak_asn1_next(cert_asn));
		
		
	}
	return -1;
	
}
